"""Двуязычный просмотр зафиксированного переноса и удержанных оценок."""
import json


def paired_comparison(evaluation):
    operator = {r["query_id"]: r for r in evaluation["modes"]["exploratory"]["rows"] if r["issued"]}
    baseline = {r["query_id"]: r for r in evaluation["modes"]["frequency"]["rows"]}
    return {"queries": len(operator), "operator_matched": sum(r["matched"] is True for r in operator.values()),
            "baseline_matched": sum(baseline[k]["matched"] is True for k in operator),
            "same_prediction": sum(r["predicted_order"] == baseline[k]["predicted_order"] for k, r in operator.items()),
            "query_ids": sorted(operator), "note": "Post-evaluation diagnostic on identical covered queries; not a new predictor"}


def markdown(data):
    e, s, p = data["evaluation"], data["sealed"], data["paired"]
    lines = ["# Перенос между исследованиями: удержанные возрастные оценки", "",
        "**Новых научных предсказаний: 0. Критерий предсказания последующей статьи не достигнут.**", "",
        "## Результат", "", "| Режим | Выдано / запросов | Совпало | Ошибок | Отказов | Точность среди выданных |",
        "|---|---:|---:|---:|---:|---:|"]
    for mode, label in [("strict", "Строгий контекстный контроль"), ("exploratory", "Согласие групп на той же паре возрастов"), ("frequency", "Частотная база")]:
        m = e["modes"][mode]
        accuracy = "—" if not m["issued"] else f'{100*m["accuracy_among_issued"]:.1f}%'
        lines.append(f'| {label} | {m["issued"]}/{m["queries"]} | {m["matched"]} | {m["wrong_order"]} | {m["abstained"]} | {accuracy} |')
    lines += ["", f'На тех же {p["queries"]} запросах оператор и база совпали с контролем по {p["operator_matched"]} и {p["baseline_matched"]} раз; одинаковых прогнозов — {p["same_prediction"]}. Преимущество оператора не показано. Отказы считаются отдельно от ошибок и не входят в точность выданных гипотез.', "",
        "## Что проверено", "",
        "Из таблицы 2 сохранённого обзора PMC6416157 подготовлены 45 оценок заболеваемости: 7 публикаций, 13 рядов «исследование × исход», 6 консервативных групп происхождения. Все 32 соседние пары возрастных диапазонов с опубликованными числами включены без выбора по результату. MCI, aMCI и naMCI не объединяются. Единицы — на 1000 человеко-лет.", "",
        "Каждый раз исключается целая группа, включая другие подтипы MCI и все её числовые ячейки. Busse 2003 и Luck 2010 объединены из-за возможного пересечения немецких выборок. Это консервативная группировка, а не экспертно подтверждённая независимость первичных когорт. Для остальных групп независимость также требует проверки первичных текстов.", "",
        "Предсказывается только порядок двух опубликованных точечных оценок: выше, ниже или одинаково. Числа не предсказываются. Это не вывод о причинности, индивидуальном старении, значимости разницы или истинном популяционном эффекте. Пять сохранённых карт проверены; числовой материал этого опыта взят из одной обзорной статьи. Первичные полные тексты не открывались.", "",
        "## Режимы", "",
        "Исследовательский оператор требует согласия минимум двух разных групп происхождения для того же исхода и той же пары возрастов. Противоречивые свидетельства дают отказ. Различия диагностических критериев, порогов SD, исключения деменции, норм, сроков и вида наблюдения, страны, календарного периода, поправки на выбытие и характеристик участников сохраняются. Это гипотеза переноса, а не подтверждение эквивалентности контекстов.", "",
        "Строгий контроль требует известных одинаковых значений всех перечисленных модификаторов. Его 32 отказа диагностируют этот строгий режим; они не доказывают, что любой научный перенос требует одинаковых стран или размеров выборок. Неизвестное значение не трактуется как равенство.", "",
        "Частотная база считает преобладающий порядок сначала внутри каждой группы, затем среди групп, для того же исхода, меры, единиц и дизайна. Она игнорирует конкретную пару возрастов и модификаторы. Результаты рядов и подтипов одной группы не выдаются за независимые подтверждения.", "",
        "## Четыре ошибки исследовательского переноса", ""]
    for row in e["modes"]["exploratory"]["rows"]:
        if row["matched"] is not False:
            continue
        c = data["controls"]["controls"][row["query_id"]]
        lines.append(f'- `{row["query_id"]}`: прогноз {row["predicted_order"]}, опубликованный порядок {row["reported_order"]}; {c["values"][0]} → {c["values"][1]}; интервалы {c["intervals"][0]} и {c["intervals"][1]}.')
    lines += ["", "Во всех четырёх случаях интервалы перекрываются. Само перекрытие не доказывает отсутствие разницы; формальный тест разницы здесь не выполнялся. Контекстные отличия видны в HTML, но не доказаны как причины ошибок. Правило после просмотра этих ошибок не изменялось.", "",
        "## Фиксация и ограничения", "",
        "Процесс прогноза прочитал только манифест и шесть разбиений. Удержанные значения и их интервалы доступны только оценщику после проверки фиксации. Точные входы, код, квитанции и хеши сохранены. Codex читал исходный обзор при подготовке разбиений: это вычислительная изоляция, не слепой научный опыт. Разбиение ретроспективное, без ограничения даты обучающих публикаций относительно удержанной. Целевая PMC10000452 не загружалась.", "",
        f'Запуск: `{s["run_id"]}`. Оценка: `{e["evaluation_id"]}`.', "",
        "Пройдено 84 Python-теста, после последнего уточнения проверки совместимости повторно пройдено 17 тестов нового модуля. Модельных вызовов: 0. Карты, GOLD и предыдущие опыты сохранены. Изменены только автономные модули эксперимента; перезапуск сервисов не требуется.", "",
        "## Следующий шаг", "",
        "Простое согласие возрастных рядов не улучшило частотную базу. Следующий опыт должен проверять условный оператор, который выбирает поддержку по контексту только на обучающих группах, и сравнивать его с базой на одинаковом покрытии. Эти четыре ошибки уже просмотрены, поэтому они пригодны для разработки и диагностики, но не для независимого доказательства успеха. До подтверждающего опыта нужна проверка происхождения первичных исследований и новый удержанный источник; правило и прогноз следует зафиксировать до открытия его результатов.", ""]
    return "\n".join(lines)


def render(data):
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return HTML.replace("__DATA__", payload)


